/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «أنوار الأنبياء» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["anwar"]={"id":"anwar","title":"أنوار الأنبياء","sub":"تأملات في المنهاج الإصلاحي للأنبياء إبراهيم وموسى عليهما السلام","author":"أحمد بن يوسف السيد","coauthors":[],"translator":"","publisher":"منار الفكر","year":"1445ه/2023م","edition":"الطبعة الثانية","series":"سلسلة أنوار الأنبياء (الجزء الأول)","lead":"تأملات وفوائد إصلاحية وتربوية من آيات قصتي إبراهيم وموسى عليهما السلام، يعرضها المؤلف مقطعاً مقطعاً ثم يعلق عليها بفوائد متتابعة. ويرى أن هذا الباب «عظيم النفع، وأن حاجة المصلحين وعامة المؤمنين إليه كبيرة».","audience":"المصلحون والدعاة والمربون والمعلمون، وعامة المؤمنين","bio":"","chapters":[{"k":"c1","t":"توطئة","q":"ما غاية الكتاب ومنهجه في تدبر قصص الأنبياء؟","essence":"تدبر المنهج الإصلاحي للأنبياء والاقتداء بهم","kw":["المنهج الإصلاحي","السنن الإلهية","التدبر"],"sections":[{"t":"غاية الكتاب","pg":7,"key":"واعتنيتُ فيها بالمنهج الإصلاحي للأنبياء، وبيان السنن الإلهية المتعلقة بنصر دينه وأوليائه والتمكين لهم، وإهلاك أعدائه وقطع دابرهم بعد الإمهال لهم، بالإضافة إلى بيان شيء من المنهج التعبدي والتزكوي للأنبياء.","p":["أما بعد، فهذا كتاب سميته ب (أنوار الأنبياء) جمعت فيه تأملات وفوائد من الآيات التي ذُكر فيها الأنبياء الكرام عليهم من الله الصلاة والسلام","أن هذا الباب عظيم النفع، وأن حاجة المصلحين وعامة المؤمنين إليه كبيرة، وأن هذا الموضوع مركزي في كتاب الله تعالى"],"items":[{"h":"ثلاثة محاور","x":"المنهج الإصلاحي للأنبياء، والسنن الإلهية في النصر والتمكين وإهلاك الأعداء، والمنهج التعبدي والتزكوي."},{"h":"الغاية العملية","x":"التأمل والتدبر ثم الاقتداء والاهتداء بهدي الأنبياء."}]},{"t":"موقعه من السلسلة","pg":8,"key":"ويُعدّ هذا الكتاب الجزءَ الأول من سلسلة أنوار الأنبياء المطبوعة، وهو متعلق باثنين من الأنبياء، وهما: (إبراهيم وموسى) عليهما صلوات الله وسلامه","p":["وهذا الكتاب يأتي ضمن منظومة من الكتب والمواد المرئية التي قدمتها في مجال التأصيل الإصلاحي"],"items":[{"h":"أجزاء قادمة","x":"وعد المؤلف بأجزاء أخرى تتعلق ببقية الأنبياء."},{"h":"منظومة التأصيل الإصلاحي","x":"التزكية للمصلحين، معالجة القرآن لنفوس المصلحين، السيرة النبوية للمصلحين، بوصلة المصلح، مركزيات الإصلاح."}]},{"t":"منهج الكتاب","pg":9,"key":"والمنهج المتبع في هذا الكتاب هو عرض مقاطع الآيات القرآنية ثم التعليق عليها بالفوائد على شكل نقاط متتابعة","p":["وأما المنهج الاستنباطي فقد ابتعدت فيه عن التكلف في الاستنباط، واجتهدت للسير فيه على ما يوافق سياق الآيات وألفاظها، وأحياناً أستشهد بأقوال المفسرين المعتبرين."],"items":[{"h":"بنية الكتاب","x":"5 مقاطع من قصة إبراهيم، و16 مقطعاً من قصة موسى، ثم خاتمة."},{"h":"التاريخ","x":"كُتبت التوطئة في 26 رمضان 1444 الموافق 17/4/2023."}]}],"quiz":[{"q":"ما الطريقة التي عرض بها المؤلف مادة كتابه؟","o":["عرض مقاطع الآيات ثم التعليق بفوائد متتابعة","سرد القصة كاملة ثم استخلاص أحكامها الفقهية","جمع أقوال المفسرين في كل آية ثم الترجيح بينها","تقسيم الكتاب أبواباً موضوعية دون نص الآيات"],"why":"والمنهج المتبع في هذا الكتاب هو عرض مقاطع الآيات القرآنية ثم التعليق عليها بالفوائد على شكل نقاط متتابعة","pg":9},{"q":"بمن يتعلق هذا الجزء الأول من سلسلة أنوار الأنبياء؟","o":["بنبيين اثنين هما إبراهيم وموسى","بأولي العزم الخمسة من الرسل","بالأنبياء المذكورين في سورة الأنعام","بسيرة النبي محمد ﷺ للمصلحين"],"why":"ويُعدّ هذا الكتاب الجزءَ الأول من سلسلة أنوار الأنبياء المطبوعة، وهو متعلق باثنين من الأنبياء، وهما: (إبراهيم وموسى) عليهما صلوات الله وسلامه","pg":8},{"q":"كيف وصف المؤلف طريقته في استخراج الفوائد؟","o":["ترك التكلف ومسايرة سياق الآيات وألفاظها","التوسع في الإشارات البعيدة لاستخراج المعاني","الاقتصار على نصوص المفسرين دون أي زيادة","الاعتماد على المقارنة بين الكتب السماوية"],"why":"وأما المنهج الاستنباطي فقد ابتعدت فيه عن التكلف في الاستنباط، واجتهدت للسير فيه على ما يوافق سياق الآيات وألفاظها","pg":9},{"q":"أي هذه الموضوعات جعله المؤلف من محاور عنايته في الكتاب؟","o":["السنن الإلهية في نصر الدين والتمكين لأهله","الإعجاز العلمي في آيات قصص الأنبياء","أنساب الأنبياء وأماكن بعثتهم وتواريخ دعواتهم","الخلافات الفقهية المستنبطة من القصص"],"why":"واعتنيتُ فيها بالمنهج الإصلاحي للأنبياء، وبيان السنن الإلهية المتعلقة بنصر دينه وأوليائه والتمكين لهم","pg":7}]},{"k":"c2","t":"أنوار من قصة إبراهيم: آيات من سورة مريم، وآيات من سورة الأنعام (1)","q":"كيف دعا إبراهيم أباه وقومه، وما الذي يتعلمه المصلح من ذلك؟","essence":"الدعوة بالعلم واللين، والبصيرة النافذة","kw":["الصديقية","اللين","البصيرة"],"sections":[{"t":"الصديقية والدعوة في البيوت","pg":14,"key":"غير أن إبراهيم عليه السلام يقوم أمام والده مقام الناصح المحاور المبيّن صاحب الحجة، وهذا تأسيس للدعوة في البيوت وللأقرباء ولو كانوا كباراً.","p":["والصديقية متعلقة بكمال التصديق بالله وخبره ووعده، كما أنها متعلقة بتمام الصدق في الأقوال والأفعال، بحيث يكون الصدّيق موافقاً بعمله قولَه تمام الموافقة."],"items":[{"h":"الآيات","x":"سورة مريم، الآيات 41 إلى 50."},{"h":"صفات الأنبياء قسمان","x":"قسم يختصون به وهو النبوة ولوازمها، وقسم يشاركهم فيه المؤمنون كالصديقية."},{"h":"الحرص والشفقة","x":"إظهار الحرص والشفقة على المدعو من هدي الأنبياء."}]},{"t":"العلم واللين لا يضمنان الاستجابة","pg":14,"key":"مقام الدعوة والإرشاد والتوجيه يتطلب استعمال الألفاظ الحسنة التي تجعل بين الداعي والمدعو جسرًا من القبول","p":["أن ثمرة العلم: «الهداية» وليس الاستكثار من المعلومات.","أن وجود الخطاب اللين، والأسلوب الحسن، والعلم؛ لا يلزم منه استجابة الطرف الآخر، بل قد يزداد عناداً"],"items":[{"h":"العلم معيار الاتباع","x":"الرشد لا يرتبط بكبر السن دائماً، فقد يهتدي الفتى بالعلم إلى ما لم يهتد إليه الشيخ."},{"h":"تعرية المعبودات الباطلة","x":"بيان عجز ما يتعلق به الناس من دون الله مع بيان تمام قدرته وغناه."},{"h":"كراهية الحق","x":"المشكلة عند أهل الباطل ليست في الأسلوب، وإنما في محبة الباطل وكراهية الحق في ذاته."}]},{"t":"الهجرة والعطاء بعد البلاء","pg":17,"key":"فإذا ضحيت في سبيل الله، وصبرت في ذلك؛ فأحسن الظن بربك، فإن عاقبة البلاء حسنة.","p":["المصلح قد تمر به مرحلة يحتاج فيها إلى الانتقال من وطنه ابتعاداً عن الباطل"],"items":[{"h":"لا يلزم الشدة","x":"صاحب الحق إذا قوبل بالتكذيب لا يلزم أن يكون موقفه شديداً، فقد قال إبراهيم: سلام عليك."},{"h":"العطاء من جنس البلاء","x":"لما اعتزل إبراهيم قومه وهب الله له إسحاق ويعقوب."}]},{"t":"البصيرة النافذة واليقين","pg":20,"key":"ولكل زمان أصنامه وفتنته وتأثيراته، فالذي يريد الوصول إلى الحق ينبغي له أن يخترق ببصيرته الحجب الظاهرة، وينظر إلى حقائق القضايا بالدليل والبرهان.","p":["وهذا يبين أهمية التفكر في آيات الله الكونية وأنها من أعظم أسباب تحصيل اليقين."],"items":[{"h":"الآيات","x":"سورة الأنعام، الآيات 74 إلى 79."},{"h":"نقد الفكرة وأصحابها","x":"منهج الأنبياء لا يقتصر على نقد العقيدة الباطلة، بل يصف من يتبناها بما يستحق."},{"h":"اليقين قبل الانطلاق","x":"المصلح يحتاج إلى اليقين قبل أن ينطلق في دعوته، كما أُري موسى آية العصا قبل لقاء فرعون."}]},{"t":"التنزل في الخطاب وإمام الحنفاء","pg":22,"key":"قد يحتاج الداعية إلى التنزّل في الخطاب مع المخالف حتى يصل إلى النتيجة الصحيحة في إبطال قول المُخالف","p":["وأما ما يسمى بالدين الإبراهيمي فالأولى به أن يسمى دين التلفيق والتحريف، لا دين الإمام الحنيف."],"items":[{"h":"مناظرة لا نظر","x":"رجّح المؤلف، تبعاً لابن كثير، أن مقام قوله «هذا ربي» مقام مناظرة."},{"h":"العقل والقلب","x":"علاقة إبراهيم بربه ليست معرفية فحسب، بل قلبية أساسها المحبة."},{"h":"المشهد الكلي","x":"لفت إبراهيم قومه من الكواكب إلى خالقها ومكوكبها."}]}],"quiz":[{"q":"شاب متعلم يرى أباه على خطأ في أمر الدين، فما الذي يستفيده من موقف إبراهيم مع أبيه؟","o":["أن مقام الولد لا يمنعه من النصح بالحجة","أن يترك نصح الكبار احتراماً لسنهم وخبرتهم","أن يكل النصيحة إلى غيره من الأقرباء","أن يواجه أباه بالغلظة حتى يظهر الحق"],"why":"غير أن إبراهيم عليه السلام يقوم أمام والده مقام الناصح المحاور المبيّن صاحب الحجة، وهذا تأسيس للدعوة في البيوت وللأقرباء ولو كانوا كباراً.","pg":14},{"q":"ما الذي جعله المؤلف الثمرة الحقيقية للعلم في خطاب إبراهيم لأبيه؟","o":["الهداية لا كثرة المعلومات","الرئاسة والتقدم على المدعوين","سعة الاطلاع وكثرة المحفوظات","إفحام المخالف وإسكاته بالحجة"],"why":"أن ثمرة العلم: «الهداية» وليس الاستكثار من المعلومات.","pg":16},{"q":"دعا رجل صديقه بأحسن أسلوب وأقوى دليل فازداد عناداً، فكيف يفسر الكتاب ذلك؟","o":["حسن الأسلوب والعلم لا يستلزمان الاستجابة","أن الداعي قصر في اختيار ألفاظه وأدلته","أن الأدلة العقلية لا تنفع في الدعوة أصلاً","أن العناد علامة ظاهرة على ضعف حجة الداعي"],"why":"أن وجود الخطاب اللين، والأسلوب الحسن، والعلم؛ لا يلزم منه استجابة الطرف الآخر، بل قد يزداد عناداً","pg":16},{"q":"ما الوجه الذي رجحه المؤلف في قول إبراهيم عن الكوكب «هذا ربي»؟","o":["مقام مناظرة تنزل فيه مع قومه","مقام نظر وبحث قبل النبوة","مقام شك عرض له ثم زال عنه سريعاً","مقام تعليم خاص بأبيه وحده"],"why":"قد يحتاج الداعية إلى التنزّل في الخطاب مع المخالف حتى يصل إلى النتيجة الصحيحة في إبطال قول المُخالف","pg":22},{"q":"لماذا يرى المؤلف أن تسمية التقريب بين الإسلام والكفر «ديناً إبراهيمياً» تعلق بأبعد الأسماء عن معناه؟","o":["لأنه إمام الحنفاء المتبرئ من الشرك دائماً","لأنه لم يكن نبياً لأهل الكتاب أصلاً","لأن قومه عبدوا الكواكب لا الأصنام","لأن اسمه لم يرد في كتب الأديان الأخرى مطلقاً"],"why":"فهو إمام الحنفاء الذي يتبرأ من الشرك دائمًا، وهذه البراءة جزء أساسي من تحقيق التوحيد لله تعالى","pg":22}],"scene":{"t":"نصيحة الوالد","x":"طالب في المرحلة الثانوية لاحظ أن والده متعلق بأمر يخالف الشرع، ويخشى أن يغضبه إن نصحه.","opts":["يحاوره بأدب ولين وحجة ويظهر له الشفقة","يسكت تماماً احتراماً لسنه ومقامه","يشدد عليه القول حتى يقطع حجته"],"why":"مقام الدعوة والإرشاد والتوجيه يتطلب استعمال الألفاظ الحسنة التي تجعل بين الداعي والمدعو جسرًا من القبول","pg":14},"rel":[{"b":"jeel","ci":3,"t":"تحدي الإيمان والثبات"}]},{"k":"c3","t":"أنوار من قصة إبراهيم: آيات من سورة الأنعام (2) والبقرة وإبراهيم","q":"ما الذي يثبت المصلح أمام الخصوم، وكيف يكون عمله ودعاؤه؟","essence":"الحجة والهداية والإمامة والدعاء بالقبول","kw":["الهداية","الإمامة","الدعاء"],"sections":[{"t":"الحجة والهداية الخاصة","pg":26,"key":"ولا يكفي امتلاك الحجة والقدرة على النقض المعرفي لقول المخالف دون أن يعيش المصلح حقيقة الهداية ونعيم الأنس بالله وبدينه.","p":["أنّ من هدي الأنبياء: الاستماع للناس، والدفاع عن الحق بالحجة والبيّنة والبرهان، بل والمبادرة إلى عرض الحق بدليله دعوة إلى الله تعالى"],"items":[{"h":"الآيات","x":"سورة الأنعام، الآيات 80 إلى 90."},{"h":"الهداية الخاصة","x":"من أعظم ما يثبت المصلح أمام حجج الخصوم ما يهبه الله له من الهداية الخاصة."}]},{"t":"الثقة بالله أمام التخويف","pg":28,"key":"كلما تشبّع قلب المصلح بالعلم بالله وعظمته وجلاله كان أعلى من المؤثرات الأرضية المحدودة أن تغيّر مفاهيمه","p":["أن أصحاب الباطل يخافون آلهتهم ورموزهم، وينسجون حولها الأساطير والخرافات التي تجعل لها الهيبة في النفوس"],"items":[{"h":"سنة متوارثة","x":"التهديد بإلحاق الضرر سنة متوارثة بين أعداء الأنبياء، كما في قصص هود ونوح."},{"h":"الفضل لله","x":"إنجازات المصلح وإن بذل فيها الجهد فالفضل فيها لله الذي يؤتيه حجته ويهديه."}]},{"t":"القدوة العملية والخوف من الشرك","pg":29,"key":"من أعظم سمات الأنبياء أنهم يحققون بأعمالهم ما يدعون إليه بأقوالهم، فكانوا نماذج عملية لا مجرد مقولات نظرية","p":["من أعظم ما ينبغي أن يخافه المصلح: أن يتسلل شيء من الشرك إلى عمله وقلبه، فإن ذلك سبب لسلب النعمة وحبوط العمل"],"items":[{"h":"أعظم ما هُدوا إليه","x":"تحقيق الاستسلام لله تعالى وتمام التوكل عليه في تبليغ الرسالة والصبر على الأذى."}]},{"t":"الإمامة والابتلاء","pg":32,"key":"أن التكليف الشرعي ابتلاء، وأن أولى الناس بإتمام متطلبات هذا الابتلاء هم الأنبياء ثم من تبعهم من الصالحين المصلحين.","p":["لا تجتمع الإمامة في الدين مع الظلم","فمن أراد أن يجعله اللهُ إمامًا فليجتنب الظلم."],"items":[{"h":"الآيات","x":"سورة البقرة، الآيات 124 إلى 131."},{"h":"مقدمات الإمامة","x":"حسن الامتثال لما أمر الله به وإتمامه، ولا ينتظر المرء أن يكون إماماً بمجرد العلم."},{"h":"الأجيال القادمة","x":"في قوله «ومن ذريتي» تنبيه إلى السعي لإيجاد الأئمة والمصلحين في الأجيال القادمة."}]},{"t":"الدعاء بالقبول وأدبه","pg":36,"key":"يستحب في الدعاء ألا يكون سؤالاً وطلباً فقط، بل يجب أن يُضمّن معنى الاعتراف والإقرار والحمد والثناء لله سبحانه وتعالى","p":["عدم الركون إلى العمل الصالح وحده مهما بذل الإنسان فيه وتعب، بل لا بد من إتباعه بالدعاء بالقبول","أن المصلح مهما بلغ من الدرجة عند الله تعالى ومن العلم بدينه فإنه يظل يدعو ربه أن يجنبه الشرك والكفر والتعلق بغيره"],"items":[{"h":"الآيات","x":"سورة إبراهيم، الآيات 35 إلى 41."},{"h":"الأوّاه","x":"رجح الطبري أن الأوّاه هو كثير الدعاء."},{"h":"الرحمة بالذرية","x":"من سمات إبراهيم الحرص على أن تصل أنوار الرسالة إلى ذريته."}]}],"quiz":[{"q":"ما الذي يقرره المؤلف بشأن قدرة المصلح على نقض أقوال المخالفين؟","o":["لا تكفي دون أن يعيش حقيقة الهداية","هي أعظم ما يثبت المصلح في طريق الحق","تغنيه عن الأنس بالله والثقة به","تكفي وحدها لثباته أمام الخصوم"],"why":"ولا يكفي امتلاك الحجة والقدرة على النقض المعرفي لقول المخالف دون أن يعيش المصلح حقيقة الهداية ونعيم الأنس بالله وبدينه.","pg":26},{"q":"حقق معلم نجاحاً كبيراً في مشروع تربوي بعد جهد طويل، فما الذي ينبغي أن يتذكره بحسب الكتاب؟","o":["أن الفضل لله الذي آتاه الحجة وسدده","أن جهده الشخصي هو سبب النجاح الأوحد","أن يعلن إنجازه ليقتدي به الآخرون","أن يطلب المنزلة عند الناس على قدر ما تعب"],"why":"فإن عليه أن يتذكر دائماً أن الفضل لله، فهو الذي يُؤتي المصلح حجته، وهو الذي يهديه ويسدده ويلهمه رشده.","pg":28},{"q":"ما الشرط الذي استنبطه المؤلف لمن أراد أن يجعله الله قدوة في الدين، من جواب الله لإبراهيم؟","o":["أن يجتنب الظلم","أن يكثر من العلم","أن يطول عمره","أن يشرف نسبه"],"why":"فمن أراد أن يجعله اللهُ إمامًا فليجتنب الظلم.","pg":32},{"q":"أنهى رجل عملاً صالحاً أتعبه كثيراً، فما الهدي الإبراهيمي بعده؟","o":["أن يتبعه بالدعاء بالقبول","أن يطمئن إلى كثرة ما عمل","أن يشرع مباشرة في عمل أكبر منه","أن يحدث الناس بما بذل فيه"],"why":"عدم الركون إلى العمل الصالح وحده مهما بذل الإنسان فيه وتعب، بل لا بد من إتباعه بالدعاء بالقبول","pg":33},{"q":"كيف ينبغي أن يكون الدعاء اقتداءً بأدعية إبراهيم الخليل؟","o":["يجمع الاعتراف والثناء إلى السؤال","يقتصر على الطلب بإلحاح وتكرار","يقدم المسألة ثم يختم بالاستغفار","يلتزم ألفاظاً مأثورة لا يزاد عليها"],"why":"يستحب في الدعاء ألا يكون سؤالاً وطلباً فقط، بل يجب أن يُضمّن معنى الاعتراف والإقرار والحمد والثناء لله سبحانه وتعالى","pg":36}],"scene":{"t":"بعد إتمام العمل","x":"أنهيت إعداد برنامج تربوي طويل لطلابك وبذلت فيه جهداً كبيراً، وأُعجب به الجميع.","opts":["تدعو الله أن يتقبله منك","تركن إلى ما بذلت من جهد","تكثر من ذكر تعبك للناس"],"why":"عدم الركون إلى العمل الصالح وحده مهما بذل الإنسان فيه وتعب، بل لا بد من إتباعه بالدعاء بالقبول","pg":33},"rel":[{"b":"lak2","ci":6,"t":"الفتاح"},{"b":"jeel","ci":10,"t":"الهداية والاستقامة"}]},{"k":"c4","t":"أنوار من قصة موسى: آيات من سورة القصص، وآيات من سورة طه (1)","q":"كيف يفهم المصلح طغيان الظالمين وطول الطريق، وبماذا يبدأ؟","essence":"سنن الله في الطغاة، والعلم بالله أولاً","kw":["الطغيان","السنن الإلهية","الصلاة"],"sections":[{"t":"الطغاة تحت علم الله","pg":40,"key":"فعليهم ألا يجعلوا ذلك سببا لليأس مهما بلغ طغيانه، فالله يرى ويسمع ويدبّر سبحانه","p":["ومن المهم للمؤمن أن يفهم سبيل المجرمين، ويفقه مناهجهم، فإن قلوبهم متشابهة وإن اختلفت أزمانهم وأدواتهم."],"items":[{"h":"الآيات","x":"سورة القصص، الآيات 1 إلى 14."},{"h":"المنفذون شركاء","x":"لم يكن فرعون يباشر الذبح بنفسه، وإنما كان المنفذون هم الجنود، ولذلك ذكرهم الله معه."},{"h":"دفع الله","x":"يدافع الله عن المستضعفين تارة بالقدر المحض وتارة بالتكليف الشرعي للمؤمنين."}]},{"t":"ميزان النصر وطول الطريق","pg":42,"key":"أن ميزان المستضعفين في توقيت النصر يختلف عن ميزان الله سبحانه وتعالى، فالمستضعفون المقهورون يريدون الفَرَج المباشر، والنصر السريع، والإهلاك العاجل للظالم","p":["فالطريق ابتدأ من ولادة موسى عليه السلام، ثم تنشئته في قصر فرعون، ثم الابتلاءات والشدائد والفتن التي صنعه الله بها، ثم الرسالة، ثم الدعوة، ثم المناظرة والتحدي، فظهور الحق، ثم الصبر الطويل، ثم كانت نهاية فرعون."],"items":[{"h":"سنن مقدرة","x":"في ميزان الله حجج وإعذار وإملاء وإمهال وابتلاء وتمحيص وشهداء وأولياء."}]},{"t":"الألطاف الإلهية وأثر العمر","pg":43,"key":"أن العُمر له تأثير على مسيرة المصلح، فالله سبحانه لم يؤتِ موسى النبوة إلا بعد أن بلغ أشده واستوى","p":[],"items":[{"h":"ألطاف عجيبة","x":"نجاة موسى بإلقائه في اليم، وتسخير زوجة فرعون، وتحريم المراضع عليه حتى يعود إلى أمه."},{"h":"بلوغ الأشد","x":"قيل الأربعون وقيل غير ذلك، والنبي ﷺ لم يُبعث إلا بعد الأربعين."}]},{"t":"أسلوب الخطاب والعلم بالله","pg":46,"key":"أن العلم بالله تعالى هو أساس الطريق بالنسبة للمصلح، وأول خطواته","p":["وهكذا ينبغي للداعية والمصلح أن يستعمل من أساليب الخطاب ما يُناسب مقام الحديث.","فليست القضية في العلم المعزول عن العمل، وإنما في العلم الحامل على العمل."],"items":[{"h":"الآيات","x":"سورة طه، الآيات 9 إلى 16."},{"h":"مقدمات عظيمة","x":"يجعل الله للأمور العظيمة مقدمات تجعل لها في النفس هيبة ومكانة، وهكذا ينبغي أن يدرك السائر في طريق الأنبياء شرفه ومسؤوليته."}]},{"t":"الصلاة والمقاصد واستحضار الساعة","pg":46,"key":"أن الصلاة من أعظم العبادات التي يحتاجها المصلح لتكون زاداً له في الطريق","p":["أهمية إدراك المقاصد من العبادات، وأنّ إجراء العبادة مع وضع العين على الثمرة والمقصد من أهم ما يحتاج المؤمن أن يُذكّر به"],"items":[{"h":"قيام الليل","x":"فرضه الله في أول الإسلام ليكون زاداً للنبي ﷺ وأصحابه في الطريق."},{"h":"استحضار الساعة","x":"استحضار الساعة وفناء الدنيا من أهم ما يُستعان به على الثبات وعدم الاغترار بالشبهات."}]}],"quiz":[{"q":"يعيش المسلمون زمناً تسلط عليهم فيه حاكم جبار، فما الموقف الذي يستفاد من مطلع سورة القصص؟","o":["ألا يجعلوا ذلك سبباً لليأس","أن ينتظروا هلاكه دون أي عمل","أن يسلموا بأن تسلطه لا يزول","أن يعتزلوا الحياة العامة كلياً"],"why":"فعليهم ألا يجعلوا ذلك سببا لليأس مهما بلغ طغيانه، فالله يرى ويسمع ويدبّر سبحانه","pg":40},{"q":"ما الفرق بين ميزان المستضعفين وميزان الله في توقيت النصر؟","o":["هم يريدونه عاجلاً ولله سنن وإمهال","هم يرونه بعيداً والله قضاه عاجلاً","الميزان واحد لكن الناس يستعجلون","الله ينصرهم فور أخذهم بالأسباب كاملة"],"why":"أن ميزان المستضعفين في توقيت النصر يختلف عن ميزان الله سبحانه وتعالى، فالمستضعفون المقهورون يريدون الفَرَج المباشر، والنصر السريع، والإهلاك العاجل للظالم","pg":42},{"q":"لماذا ذكر الله جنود فرعون معه في وصف الخطأ، مع أنه هو الآمر بذبح الأطفال؟","o":["لأن المنفذين شركاء في جريمة الطاغية","لأن الجنود هم أصحاب الرأي في الذبح","لأن هامان كان يأمر بالذبح دون علم فرعون","لأن العقوبة تعم أهل البلد جميعاً"],"why":"فهو لم يكن يُباشر تمرير السكين على رقاب الأطفال وإنما كان يأمر بذلك، والمنفذون هم الجنود، ولذلك قال سبحانه","pg":41},{"q":"ما المعيار الذي استنبطه المؤلف من ترتيب ﴿إِنَّنِي أَنَا اللَّهُ لَا إِلَٰهَ إِلَّا أَنَا فَاعْبُدْنِي﴾؟","o":["أن يكون العلم حاملاً على العمل","أن يكون العلم واسعاً بالأقوال","أن يسبق العلم العمل بزمن طويل جداً","أن يُحفظ النص كاملاً دون تفصيل"],"why":"فليست القضية في العلم المعزول عن العمل، وإنما في العلم الحامل على العمل.","pg":46},{"q":"لماذا فرض الله قيام الليل في أول الإسلام بحسب ما ذكره المؤلف؟","o":["ليكون زاداً للنبي ﷺ وأصحابه في الطريق","ليميز المؤمنين عن المنافقين في المدينة","ليعوض قلة العبادات المفروضة يومئذ","ليتفرغوا للقرآن بعيداً عن أعين قريش"],"why":"ومما يؤيّد ذلك: أن الله فرض قيام الليل في أول الإسلام على النبي ﷺ وأصحابه ليكون زاداً لهم في الطريق.","pg":46}],"scene":{"t":"طول الطريق","x":"معلم بدأ مشروعاً إصلاحياً في مدرسته منذ عامين، ولم ير بعد النتائج التي كان يرجوها.","opts":["يصبر ويعلم أن للطريق مراحل","ييأس ويترك المشروع كله","يستعجل النتائج بأي وسيلة"],"why":"فالطريق ابتدأ من ولادة موسى عليه السلام، ثم تنشئته في قصر فرعون، ثم الابتلاءات والشدائد والفتن التي صنعه الله بها، ثم الرسالة، ثم الدعوة، ثم المناظرة والتحدي، فظهور الحق، ثم الصبر الطويل، ثم كانت نهاية فرعون.","pg":42}},{"k":"c5","t":"أنوار من قصة موسى: آيات من سورة طه (2)، وآيات من سورة القصص (2)","q":"كيف أعد الله موسى للرسالة، وما الذي يحتاجه المصلح قبل الانطلاق؟","essence":"التدريب واليقين والأعوان والعلم بالله","kw":["التهيئة","اليقين","المؤازرة"],"sections":[{"t":"فهم المقاصد والتدريب","pg":50,"key":"المصلح يحتاج إلى التدريب والتجربة قبل الانطلاق في المشاريع الإصلاحية الكبيرة الصعبة","p":["أنّ الإنسان الفطن يحاول إدراك مقاصد الألفاظ والأسئلة ولا يقف عند ظاهرها فقط"],"items":[{"h":"الآيات","x":"سورة طه، الآيات 17 إلى 36."},{"h":"العصا","x":"هيأ الله موسى وعلمه كيف يتعامل مع العصا حين تستحيل حية، فسهل عليه ذلك أمام فرعون."}]},{"t":"الطمأنينة واليقين","pg":51,"key":"أهمية العناية بتعزيز اليقين وتثبيت الإيمان في سياق إعداد الدعاة وبناء المصلحين.","p":["المصلح يحتاج إلى تثبيت وطمْأنة، خاصة إذا كثرت المخاوف وصعب الطريق وكثرت أعباؤه"],"items":[{"h":"البصيرة","x":"من المهم أن ينطلق المصلح في رسالته وهو موقن بصحتها، فيكون على بصيرة وبينة."},{"h":"الحجج","x":"المصلح المتبع للأنبياء يحرص أن يكون مبيناً في دعوته، مستدلاً بالحجج الصحيحة."}]},{"t":"الوزراء والمدد","pg":52,"key":"أن المصلح يحتاج إلى المدد في شأنه الداخلي والخارجي، ففي داخل نفسه يحتاج إلى انشراح الصدر، وفي الخارج يحتاج إلى تيسير الأمر ويحتاج إلى الأعوان والأنصار.","p":["فالطغيان لا يستمر، لكن ذلك بميزان الله وليس بميزاننا."],"items":[{"h":"الافتقار والرفقة","x":"الإنسان مهما بلغ يحتاج إلى الافتقار لله، وإلى رفقاء مؤنسين ووزراء معينين."},{"h":"الذكر غاية","x":"الله يحب كثرة ذكره وتسبيحه، ولذلك توسل به موسى في دعائه."}]},{"t":"مركزية العلم بالله","pg":56,"key":"مركزية العلم بالله تعالى في بداية طريق المصلح، فهو أساس كل علم، وكل الأعمال القلبية تبدأ منه.","p":["فإذا تحقق العلمُ بالله في نفس المؤمن عبر الطرق المذكورة؛ فإنه يكون سببًا لثلاثة أصول عظيمة من أصول العبودية، هي القواعد الكبرى لأعمال القلوب، وهي: (اليقين، والمحبة، والخشية)."],"items":[{"h":"الآيات","x":"سورة القصص، الآيات 29 إلى 35."},{"h":"طرق العلم بالله","x":"التدبر في كتاب الله، والتفكر في مخلوقاته، والاعتبار بأقداره وأيامه ومعرفة سننه، والبصيرة بسبيل أنبيائه، والعمل المورث المزيد من الهداية."},{"h":"التهيئة الداخلية","x":"بقدر تكليف المصلحين وصعوبة ما يواجهون يحتاجون إلى التهيئة واليقين والبراهين."}]},{"t":"موجبات الإصلاح والمؤازرة","pg":58,"key":"أنّ وجود المشاركين للمصلح في طريقه، المؤازرين له، من أهمّ ما يشد من عضده، ويقويه، ويسهل عليه مواجهة التحديات والمصاعب","p":["وأن تحرير المستضعفين مجال إصلاحي من أعظم المجالات."],"items":[{"h":"مشكلات توجب الإصلاح","x":"وجود الظلم والفسق والطغيان، وهي أسباب شرعية لوجود المصلحين."}]}],"quiz":[{"q":"لماذا أجاب موسى عن سؤال ﴿وَمَا تِلْكَ بِيَمِينِكَ يَا مُوسَىٰ﴾ بذكر منافع العصا لا باسمها فقط؟","o":["لأنه فهم أن السؤال متجاوز للماهية","لأنه أراد إطالة الحديث مع ربه وحده","لأنه لم يعرف ما المقصود من السؤال","لأن العصا لم يكن لها اسم معروف"],"why":"ولكنه فهم من السياق أنّ السؤال كان متجاوزًا للماهيّة، فذكر استعمالات العصا كذلك.","pg":50},{"q":"لماذا أرى الله موسى انقلاب العصا حية في الوادي قبل لقاء فرعون؟","o":["ليتمرس قبل المهمة الكبيرة أمام الطاغية","لأن المعجزة لا تتكرر إلا بعد تجربتها","لأن الخوف من الحية عيب ينبغي إزالته","لأن فرعون كان يعرف السحر فاحتاج إلى مثله"],"why":"المصلح يحتاج إلى التدريب والتجربة قبل الانطلاق في المشاريع الإصلاحية الكبيرة الصعبة","pg":50},{"q":"ما الذي يدل عليه دعاء موسى ﴿وَاجْعَل لِّي وَزِيرًا مِّنْ أَهْلِي﴾ في حياة المصلح؟","o":["حاجته إلى رفقاء مؤنسين وأعوان معينين","عجزه عن حمل الرسالة إلا بأقاربه","أن القيادة لا تصح إلا جماعية في كل حال","أن الأخ أولى بمشاركة الدعوة من غيره"],"why":"أن الإنسان مهما بلغ في العلم والإيمان والمنزلة عند الله فهو يحتاج دوماً إلى الافتقار والتذلل لله والاستعانة به، وأنه يحتاج كذلك إلى رفقاء مؤنسين ووزراء معينين","pg":52},{"q":"إذا تحقق العلم بالله في نفس المؤمن، فما الأصول القلبية التي يثمرها بحسب المؤلف؟","o":["اليقين والمحبة والخشية","الحفظ والفهم والتطبيق","الصبر والشكر والرضا بالقدر","الخوف والرجاء والتوكل عليه"],"why":"فإذا تحقق العلمُ بالله في نفس المؤمن عبر الطرق المذكورة؛ فإنه يكون سببًا لثلاثة أصول عظيمة من أصول العبودية، هي القواعد الكبرى لأعمال القلوب، وهي: (اليقين، والمحبة، والخشية).","pg":57},{"q":"ما الذي يعده المؤلف من أعظم ميادين الإصلاح استناداً إلى سبب إرسال موسى؟","o":["تحرير المستضعفين من الظلم","تعليم الناس فنون الخطابة","بناء المعابد وإقامة الشعائر","جمع الأموال لدعم الدعوة"],"why":"وأن تحرير المستضعفين مجال إصلاحي من أعظم المجالات.","pg":58}],"scene":{"t":"مهمة كبيرة","x":"كُلّفت بقيادة مبادرة تربوية واسعة في مدرستك، والمهمة أكبر من أن ينهض بها واحد.","opts":["تطلب زميلاً معيناً يشد عضدك","تتحمل المهمة كلها وحدك","تعتذر عن المهمة من أولها"],"why":"أنّ وجود المشاركين للمصلح في طريقه، المؤازرين له، من أهمّ ما يشد من عضده، ويقويه، ويسهل عليه مواجهة التحديات والمصاعب","pg":58},"rel":[{"b":"jeel","ci":3,"t":"تحدي الإيمان والثبات"}]},{"k":"c6","t":"أنوار من قصة موسى: آيات من سورة طه (3) و(4)","q":"كيف يصنع الله أولياءه، وكيف يدعو المصلح الطغاة؟","essence":"الصناعة الربانية والدعوة باللين","kw":["الرعاية","القول اللين","المعية"],"sections":[{"t":"التهيئة والرعاية","pg":59,"key":"أن الرسالة الإصلاحية كلما عظمت متطلباتها، وكانت الأخطار المحدقة بها شديدة؛ فإن ذلك يتطلب مزيداً من التهيئة لحاملها والتربية له","p":["أنّ الإنسان وإن كان تحت رعاية الله وعنايته؛ فهذا لا يعني أنّه لن يتعرّض للفتن والمصاعب، بل قد تكون تلك الفتن والمصاعب من مقتضى عناية الله بالمؤمن ليصنعه ويربيه ويهيئه."],"items":[{"h":"الآيات","x":"سورة طه، الآيات 37 إلى 41."},{"h":"الحفظ","x":"إذا أراد الله حفظ عبده رعاه ولو أحدقت به الأهوال من كل اتجاه."}]},{"t":"القبول والقدر","pg":60,"key":"إذا وضع الله القبول في الأرض لعبدٍ؛ فلا يمكن لأحد أن يضع حاجزًا بينه وبين قلوب الناس","p":["والمستفاد من ذلك أن يدرك المصلح أنه إذا قدّر الله له الرفعة والسبق وقسم له الخير؛ فإنه سيُساق إلى قدره، فليطمئن، وليبذل ما عليه، فالله وليّه ومولاه."],"items":[{"h":"خطوات مكتوبة","x":"سار موسى من مدين لا يدري ما ينتظره، وكل خطوة كانت مكتوبة في القدر."}]},{"t":"غاية الدعوة واللين","pg":64,"key":"أن مقام الدعوة والتذكير يجب أن يكون مصحوباً بالقول اللين، والخطاب الحسن، فإن الثمرة لا تتحقق إلا بذلك.","p":["هذا الدين جاء لإصلاح الناس وهدايتهم، ولم يأتِ للانتقام منهم","أن وجود الخطاب اللين والقول الحسن لا يقتضي استجابة المدعوّ، فقد يمنعه هواه، أو جاهه وسلطانه."],"items":[{"h":"الآيات","x":"سورة طه، الآيات 42 إلى 53."},{"h":"الوظيفة الأولى","x":"آلام المستضعفين مهما بلغت لا ينبغي أن تنسي المصلح أن وظيفته الأولى الدعوة إلى الله."}]},{"t":"معية الله ودوام الذكر","pg":64,"key":"أن اليقين بمعية الله من أعظم ما يُطمئن المصلح في مسيرته ودعوته","p":["الأنبياء بشر، ففيهم غريزة الخوف"],"items":[{"h":"خصال تحقق المعية","x":"العلم بالله وشريعته وسننه، وتمام التصديق بأخباره، واستحضار مراقبته، وتمام التوكل، ودوام الاستهداء، والصبر وعدم استعجال الثمرة."},{"h":"دوام ذكر الله","x":"من أعظم ما يعين المصلح على أداء رسالته ومكابدة المصاعب."}]},{"t":"تحرير المستضعفين ومشكلات العصر","pg":66,"key":"أن وجود مشكلة كبيرة في زمن المصلح لا ينبغي أن تُغفله عن المشكلة في أصل الدين وأساسه؛ لأن الأنبياء اعتنوا بكليهما.","p":["أن تحرير المستضعفين من أعظم المقاصد الإصلاحية الشريفة"],"items":[{"h":"مشكلة كل عصر","x":"اعتنى لوط بالفاحشة، وشعيب بالتطفيف، وموسى بالمستضعفين."},{"h":"زماننا","x":"من أهم مشكلات زماننا مشكلة الاستضعاف والقهر للمؤمنين في كثير من بقاع الأرض."}]},{"t":"أصول الحوار والترغيب والترهيب","pg":67,"key":"ينبغي على الداعية أن يتنبه لأصول الحوار الصحيح، فلا ينزلق إلى المغالطات والمُشتِّتات التي يطرحها الخصم، بل يُركز على القضية الأساسية","p":["أن الإنذار بذكر العذاب لا يتعارض مع القول اللين، وأن من المهم للمصلح أن يجمع بين الترغيب والترهيب"],"items":[{"h":"رد فرعون","x":"مع الحجج والأسلوب الطيب كان رد فرعون مليئاً بالعناد والكذب والتشويه."}]}],"quiz":[{"q":"كيف ينبغي أن يفهم المصلح تعرضه للشدائد مع أنه في رعاية الله؟","o":["قد تكون الفتن من عناية الله ليصنعه","الشدائد علامة على غضب الله عليه","الرعاية تعني السلامة من كل أذى","الشدائد دليل على خطأ طريقه كله من أوله"],"why":"بل قد تكون تلك الفتن والمصاعب من مقتضى عناية الله بالمؤمن ليصنعه ويربيه ويهيئه.","pg":60},{"q":"سعى فرعون بكل أدواته لتشويه سمعة موسى، فلماذا لم يفلح بحسب المؤلف؟","o":["لأن الله ألقى على موسى محبة منه","لأن قوم فرعون كانوا يحبون الأنبياء","لأن موسى رد على التشويه بمثله","لأن أدوات فرعون الإعلامية كانت ضعيفة"],"why":"إذا وضع الله القبول في الأرض لعبدٍ؛ فلا يمكن لأحد أن يضع حاجزًا بينه وبين قلوب الناس","pg":60},{"q":"ما الوظيفة الأولى التي لا ينبغي أن ينساها المصلح حتى مع أشد الطغاة؟","o":["الدعوة إلى الله لا الانتقام","فضح الطاغية أمام الناس جميعاً","الثأر لآلام المستضعفين","إسقاط حكمه بأي وسيلة كانت"],"why":"هذا الدين جاء لإصلاح الناس وهدايتهم، ولم يأتِ للانتقام منهم","pg":63},{"q":"ما الذي يعده المؤلف من أعظم ما يعين المصلح على مكابدة المصاعب، أخذاً من وصية موسى وهارون؟","o":["المداومة على ذكر الله","الإكثار من الأتباع والأنصار","التمكن من قوة البيان","الاستعداد بالمال والعدة"],"why":"أن من أعظم ما يعين المصلح على أداء رسالته ومكابدة المصاعب ومواجهة التحديات: (دوام ذكر الله)","pg":65},{"q":"مصلح يعيش في بلد ظاهر الظلم، فهل يكفيه أن يعتني بمشكلة الظلم وحدها؟","o":["لا، بل يعتني معها بأصل الدين وأساسه","نعم، لأنها أعظم مشكلات عصره كلها","نعم، حتى يزول الظلم ثم يلتفت إلى غيره","لا، بل يترك قضايا الناس للعبادة"],"why":"أن وجود مشكلة كبيرة في زمن المصلح لا ينبغي أن تُغفله عن المشكلة في أصل الدين وأساسه؛ لأن الأنبياء اعتنوا بكليهما.","pg":66}],"scene":{"t":"مغالطات في الحوار","x":"تحاور شخصاً في قضية أساسية من قضايا الدين، فيكثر من طرح مسائل جانبية تشتت النقاش.","opts":["تختصر ثم تعيد الحديث إلى القضية الأساسية","تتتبع كل مسألة جانبية بالتفصيل","تنهي الحوار فوراً"],"why":"ينبغي على الداعية أن يتنبه لأصول الحوار الصحيح، فلا ينزلق إلى المغالطات والمُشتِّتات التي يطرحها الخصم، بل يُركز على القضية الأساسية","pg":67}},{"k":"c7","t":"أنوار من قصة موسى: آيات من سورة طه (5) و(6)","q":"كيف يواجه المصلح الباطل، وما الذي ثبت السحرة أمام فرعون؟","essence":"المواجهة الحكيمة واليقين الذي يصنع الثبات","kw":["المواجهة","اليقين","الثبات"],"sections":[{"t":"تشويه الحق واغترار الطغاة","pg":70,"key":"أنّه ليس كلّ من عادى الحق فلجهله به، بل قد يكون عالماً به ولكنه مغترٌّ بما لديه.","p":["أنّ من سُنة الطغاة والمكذبين: تشويه رسالة الحق وتشويه حَمَلة الحق"],"items":[{"h":"الآيات","x":"سورة طه، الآيات 57 إلى 69."},{"h":"تهمتان","x":"رمى فرعون موسى بأنه ساحر، وبأنه جاء ليخرجهم من أرضهم."},{"h":"تصديق الخيالات","x":"يغتر الطغاة بكذبهم ويصدقون خيالاتهم حتى يواجهوا الحقيقة بعد فوات الأوان."}]},{"t":"الإقدام والحرص على الهداية","pg":71,"key":"إذا بدت بوادر المواجهة الحتمية مع أهل الباطل؛ فعلى المصلح أن يُقْدِم ويواجِه","p":["وهذه الساحات يحبها الله تعالى، وهي ساحات الفرقان التي يُفرَق فيها بين الحق والباطل.","عدم اليأس من تكرار الدعوة، ولو كان المدعوُّ تُستبعَد منه الاستجابة، فقد تنفذ الكلمة إلى باطنه وتُحدِث أثرها ولو بعد حين."],"items":[{"h":"هداية الخلق","x":"على المصلح ألا ينسى حرصه على هداية الخلق حتى في ساحات المواجهة."}]},{"t":"نفوس أهل الباطل","pg":72,"key":"أن من أكبر أسباب رفض الحق: الخوف من فقدان المكاسب الشخصية","p":["أن المنغمس في الباطل يصعب عليه إدراك النيات الحسنة للطاهرين، فهو يظن أن كل الناس مثله"],"items":[{"h":"ضعف البواطن","x":"أهل الباطل وإن عظمت صورتهم قد يضعفون ويترددون في بواطنهم."},{"h":"رهبة لا تعيب","x":"قد يقع في نفس المصلح شيء من الرهبة، ولا يكون نقصاً إذا لم يصرفه عن واجبه."},{"h":"أحوج الناس إلى التثبيت","x":"المتصدرون لمواجهة أهل الباطل."},{"h":"ما يثبت في الصراع","x":"النظر إلى حقيقة الباطل وضعف قواعده، ومقارنته بجلال الحق."}]},{"t":"اليقين وسطوة الحق","pg":75,"key":"أنّ اليقين بصحّة الحقّ، ورؤية البراهين القطعية المؤيدة له، من أهم ما يجعل المسلم ثابتًا على الحق ولو كان هذا الثبات محفوفاً بأشدّ المخاطر.","p":["فالسبب الذي جعل السحرة يثبتون أمام تهديد فرعون هو يقينهم التام بصحة رسالة موسى عليه السلام لأنهم كانوا أعلم الناس بالسحر وطرائقه"],"items":[{"h":"الآيات","x":"سورة طه، الآيات 70 إلى 73."},{"h":"سبيل المجرمين","x":"من موضوعات القرآن المهمة معرفة سبيل المجرمين وفهم نفسياتهم ودوافعهم."}]},{"t":"منطق المتكبرين واستحضار الآخرة","pg":77,"key":"فليتنبّه المؤمن في كل زمان إلى هذا المنطق، ولا يربط بين العلو المادي وبين الحق.","p":["وبعكس ذلك فإن الانغماس في الدنيا، والاستغراق فيها، وغياب استحضار الآخرة؛ من أهم ما يُضعِف المؤمن ويُسقطه أمام الأزمات."],"items":[{"h":"التهديد والوعيد","x":"منطق المتكبرين في مواجهة الحقيقة هو التهديد والركون إلى القوة المادية."},{"h":"القلوب لا الأجساد","x":"الشأن في القلوب والأرواح وما تحمله من معاني الإيمان، لا في الأجساد."},{"h":"حديث الوهن","x":"أورد المؤلف حديث تداعي الأمم وتفسير الوهن بحب الدنيا وكراهية الموت."}]}],"quiz":[{"q":"هل كل من عادى الحق كان جاهلاً به بحسب الكتاب؟","o":["لا، فقد يعلمه ويغتر بما لديه","نعم، فلو عرف الحق لاتبعه فوراً","نعم، لأن العداوة لا تكون إلا عن جهل","لا، فكل معاد للحق يعرفه يقيناً"],"why":"أنّه ليس كلّ من عادى الحق فلجهله به، بل قد يكون عالماً به ولكنه مغترٌّ بما لديه.","pg":70},{"q":"لماذا اختار موسى يوم الزينة وضحى النهار موعداً للقاء السحرة؟","o":["لأنها ساحة فرقان بين الحق والباطل","لأن فرعون اشترط عليه ذلك الموعد","لأنه وقت فراغ السحرة من أعمالهم","ليتمكن من الانسحاب بسهولة إن غلبوه"],"why":"وهذه الساحات يحبها الله تعالى، وهي ساحات الفرقان التي يُفرَق فيها بين الحق والباطل.","pg":71},{"q":"لماذا وعظ موسى السحرة قبل المناظرة مع أنهم جاؤوا لمغالبته؟","o":["لأنه لا ينسى هداية الخلق في المواجهة","ليؤخر المناظرة حتى يجتمع الناس كلهم إليه","ليخيفهم فينسحبوا قبل بدء المناظرة","لأنه شك في قدرته على غلبتهم جميعاً"],"why":"على المصلح ألا ينسى حرصه على هداية الخلق حتى في ساحات المواجهة","pg":71},{"q":"ما الذي يثبت الإنسان في مقام الصراع المباشر مع أهل الباطل؟","o":["أن يقارن ضعف الباطل بجلال الحق","أن يكثر من مجالسة أهل الباطل","أن يهون من شأن المواجهة ويتجاهلها","أن يعتمد على عدد أنصاره وحده"],"why":"من أكثر ما يُثبّت الإنسان في مقام الصراع المباشر مع أهل الباطل: أن ينظر إلى حقيقة الباطل ومقدار فساده وضعف قواعده، ويقارنه بجلال الحق","pg":73},{"q":"ما الذي جعل السحرة يثبتون أمام تهديد فرعون بتقطيع الأيدي والأرجل؟","o":["يقينهم التام بصحة رسالة موسى","خوفهم من انتقام بني إسرائيل منهم","طمعهم في منزلة رفيعة عند موسى","جهلهم بقسوة عذاب فرعون وشدته"],"why":"فالسبب الذي جعل السحرة يثبتون أمام تهديد فرعون هو يقينهم التام بصحة رسالة موسى عليه السلام","pg":75}],"scene":{"t":"مواجهة لا بد منها","x":"طُلب منك أن ترد في لقاء عام على شبهات يروجها متحدث مشهور بين الشباب.","opts":["تُقدم وتواجه بالحجة وتحرص على هدايته","تنسحب خوفاً من شهرته","تهاجمه في شخصه لتسقطه"],"why":"إذا بدت بوادر المواجهة الحتمية مع أهل الباطل؛ فعلى المصلح أن يُقْدِم ويواجِه","pg":71},"rel":[{"b":"jeel","ci":3,"t":"تحدي الإيمان والثبات"}]},{"k":"c8","t":"العبر والفوائد من المراحل التالية في قصة موسى: آيات من سورة الأعراف، وآيات من سورة يونس","q":"ماذا يفعل المصلحون حين يهيمن الظالمون ويطول الاستضعاف؟","essence":"معالم الصبر والتربية زمن الاستضعاف","kw":["الاستضعاف","الشباب","التوكل"],"sections":[{"t":"مرحلة جديدة","pg":79,"key":"ثم انتقلت الأحداث إلى مرحلة جديدة، وهي مرحلة الصبر والثبات على الإيمان، والابتعاد عن أعين الظلمة والمتجبرين، مع الفأل وحسن الظن والاتباع.","p":["من يتأمل قصص الأنبياء يفهم منها أن الإصلاح إذا كان في مرحلة علو كلمة المجرمين وشدة هيمنتهم فإنّ على المصلحين فعل ما يمكنهم وليس عليهم تغيير كل شيء"],"items":[{"h":"الآيات","x":"سورة الأعراف، الآيات 127 إلى 133."},{"h":"نفوس الطغاة","x":"نفوس الطغاة المتكبرين لا تخضع للحق، فقد ازداد فرعون طغياناً بعد ظهور الحق."}]},{"t":"معالم هدي الأنبياء زمن هيمنة الظالمين","pg":83,"key":"تربية المؤمنين على التفاؤل والاستبشار بحسن العاقبة ومحاربة اليأس","p":["وإذا تأمّلنا هدي الأنبياء في مثل هذه المرحلة التي يهيمن فيها الظالمون فسنخرج بهذه المعالم:"],"items":[{"h":"تبليغ الحق","x":"وإقامة الحجة بالأسلوب اللين."},{"h":"مواجهة المبطلين","x":"بحجج الحق ودحض أباطيلهم وإعلاء كلمة الحق."},{"h":"العناية بالمؤمنين","x":"وتربيتهم على العبادة والصبر والثبات والتوكل."},{"h":"التفاؤل","x":"ومحاربة اليأس."},{"h":"الابتعاد عن بلد الظلم","x":"بعد ظهور الحق وتمادي الباطل، كما في الهجرة."},{"h":"اتباع الوحي","x":"والثقة بمعية الله ووعده."}]},{"t":"ابتلاء الاستضعاف وابتلاء التمكين","pg":86,"key":"أن لمرحلة الاستضعاف ابتلاءاتها، ولمرحلة التمكين ابتلاءاتها","p":["فالشأن ليس في مجرد الاستخلاف في الأرض، وإنما في العمل بعد الاستخلاف","فالميزان الإلهي يختلف عن الميزان البشري."],"items":[{"h":"طول البلاء","x":"البلاء على المستضعفين قد يطول ويمتد لأزمنة طويلة."},{"h":"حلم الله","x":"أمهل الله فرعون وقومه وفتح لهم أبواباً متتالية من الآيات قبل أن ينتقم منهم."}]},{"t":"الشباب أمل الدعوة","pg":90,"key":"فعلى المصلحين أن يُركّزوا على الشباب في البناء والتربية والتهيئة للدعوة والإصلاح وحمل رسالة الإسلام.","p":["أن الفتيان والشباب مِن أكثر من يُرجى صلاحهم واستجابتهم للدعوة ثم حمل أعبائها"],"items":[{"h":"الآيات","x":"سورة يونس، الآيات 83 إلى 88."},{"h":"إيمان في الخوف","x":"آمن هؤلاء الشباب في حال خوف واستضعاف، فالمؤمن ولو كان صغيراً يمكنه تحمل أعباء الإيمان."},{"h":"خوف الفتنة","x":"أعظم ما خافوه الفتنة في الدين، أكثر من خوفهم على نقص دنياهم."}]},{"t":"التوكل والدعاء والصلاة والتبشير","pg":91,"key":"أن من أعظم ما ينبغي على المؤمن تذكره عند هيمنة الظالمين المفسدين: تحقيق التوكل على الله سبحانه وتعالى","p":["أهمية التبشير أوقات الاستضعاف والأزمات والفتن، وهذا من أهم أدوار المصلحين الثابتين"],"items":[{"h":"مقامات التوكل","x":"التوكل على الله في الثبات على الدين، وفي دفع أذى الأعداء، وفي فتح أبواب الفرج."},{"h":"الدعاء","x":"التزام الدعاء في أزمنة الاستضعاف، كقوله: ربنا لا تجعلنا فتنة للقوم الظالمين."},{"h":"البيوت والصلاة","x":"حرص المؤمنين على البعد عن مصدر الفتنة، وتقاربهم، ومركزية الصلاة في حياتهم."}]}],"quiz":[{"q":"في مرحلة علو المجرمين وشدة هيمنتهم، ما الذي على المصلحين بحسب الكتاب؟","o":["فعل ما يمكنهم دون تكليف بتغيير كل شيء","تغيير كل شيء دفعة واحدة ولو بالقوة","اعتزال الناس حتى تنقضي المرحلة كلها بسلام","مداهنة الظالمين حفاظاً على الدعوة"],"why":"فإنّ على المصلحين فعل ما يمكنهم وليس عليهم تغيير كل شيء","pg":82},{"q":"أي هذه الأعمال جعله المؤلف من معالم هدي الأنبياء حين يهيمن الظالمون؟","o":["تربية المؤمنين على التفاؤل ومحاربة اليأس","تأجيل تبليغ الحق حتى يزول الظلم","الانشغال بالرد على كل شبهة تفصيلاً","حمل المستضعفين على المواجهة المسلحة فوراً"],"why":"تربية المؤمنين على التفاؤل والاستبشار بحسن العاقبة ومحاربة اليأس","pg":83},{"q":"ما ابتلاء مرحلة التمكين بحسب المؤلف؟","o":["فتنة الدنيا والتنافس والتحاسد والغرور","القتل والأسر والتعذيب والاستعباد","المنع من التعبد وإقامة شعائر الدين علناً","الاستهزاء والسخرية من المؤمنين"],"why":"وأما ابتلاء مرحلة التمكين ففتنة الدنيا والتنافس والتحاسد والتدابر والغرور","pg":86},{"q":"لماذا يدعو المؤلف المصلحين إلى العناية بالفئة التي آمنت بموسى أولاً من قومه؟","o":["لأنهم أكثر من يرجى صلاحهم وحملهم للدعوة","لأن الكبار لا يقبلون الحق مهما دُعوا إليه","لأنهم أقل تعرضاً للفتن والضغوط من غيرهم","لأنهم أكثر الناس فراغاً ووقتاً للعمل"],"why":"أن الفتيان والشباب مِن أكثر من يُرجى صلاحهم واستجابتهم للدعوة ثم حمل أعبائها","pg":89},{"q":"ما الذي خافه الشباب الذين آمنوا مع موسى أكثر من غيره؟","o":["أن يفتنوا في دينهم","أن تنقص أموالهم ودنياهم","أن يفقدوا أهلهم وبيوتهم","أن يبطش بهم جنود فرعون"],"why":"أن أعظم ما خافه هؤلاء الشباب الذين آمنوا مع موسى عليه السلام إنما هو الفتنة في الدين، أكثر من خوفهم على نقص دنياهم","pg":91}],"scene":{"t":"زمن الأزمة","x":"يمر المجتمع بأزمة شديدة، ويلاحظ المعلم أن طلابه يتحدثون بيأس عن المستقبل.","opts":["يبشرهم ويثبتهم ويذكرهم بحسن العاقبة","يؤكد لهم أن الأمر لا أمل فيه","يتجنب الحديث عن الأزمة تماماً"],"why":"أهمية التبشير أوقات الاستضعاف والأزمات والفتن، وهذا من أهم أدوار المصلحين الثابتين","pg":93},"rel":[{"b":"lak2","ci":6,"t":"الفتاح"},{"b":"jeel","ci":10,"t":"الهداية والاستقامة"}]},{"k":"c9","t":"أنوار من قصة موسى: آيات من سورة الشعراء، وآيات من سورة الأعراف (2)","q":"ما سنن الله في إهلاك الظالمين وتوريث الأرض للصالحين؟","essence":"مصارع الظالمين ووراثة الصابرين","kw":["المعية","وراثة الأرض","الصبر"],"sections":[{"t":"آلة التشويه الفرعونية","pg":95,"key":"ومن الواضح كذلك أن الآلة الإعلامية للحكومة الفرعونية تعمل بنشاط وفي جميع الحالات","p":["وهذه سنة مستمرة في الظالمين والمجرمين، يستعملون نفس الأسلوب، وما أشبه الليلة بالبارحة."],"items":[{"h":"الآيات","x":"سورة الشعراء، الآيات 52 إلى 67."},{"h":"قوة فرعون","x":"استطاع أن يحشد المقاتلين من كل المدائن بسرعة حتى أدرك موسى في زمن يسير."}]},{"t":"مصارع الظالمين","pg":96,"key":"إهلاك الظالمين أمر عظيم، يُحبّ الله تعالى منا أن نتفكر فيه، ونقف عنده، ونتأمله، ونعتبر به","p":["وإذا كان هذا في التاريخ فإن سنة الله لا تزال جارية، فليعتبر المؤمن بمصارع الظالمين"],"items":[{"h":"فرعون","x":"أكثر طاغية جرى ذكره في القرآن."}]},{"t":"المعية ليست للأنبياء وحدهم","pg":97,"key":"من أعظم ما يحتاجه قادة المصلحين المتبعين للأنبياء: الثقة بالله والتوكل عليه والإيمان بمعيته","p":["فالمعية لا تخص الأنبياء وحدهم."],"items":[{"h":"سنن ماضية","x":"وإن انقطع الوحي فإن سنن الله ماضية لا تتبدل، ومنها نصر المؤمنين الصابرين المتقين."},{"h":"معية للصابرين والمتقين","x":"ذكر الله في كتابه معيته للصابرين وللمتقين."}]},{"t":"وراثة الأرض","pg":99,"key":"أنّ مما يحبه الله ويقدره سبحانه: وراثة المؤمنين أرض الكفار، ووراثة المستضعفين أرض الظالمين","p":["وموضوع وراثة الأرض مهم جداً في فهم سنن الله تعالى"],"items":[{"h":"الآيات","x":"سورة الأعراف، الآيات 136 و137."},{"h":"سنة الاستبدال","x":"سنة مقاربة لوراثة الأرض ينبغي أن يتفكر فيها المصلحون."}]},{"t":"صفات الوارثين","pg":101,"key":"أنّ الصفة المركزية التي جعلها الله سبباً لتوريث بني إسرائيل الأرض هي (الصبر)","p":["فإن الشأن كل الشأن في القدَر والسُّنن"],"items":[{"h":"صفات يتحلى بها الوارثون","x":"التوكل، والصبر، والتقوى، والعلم، والاستمساك بالوحي، ومحبة الله، والذلة للمؤمنين، والعزة على الكافرين، والجهاد، وعدم الخوف من الخلق في ذات الله، والصلاح."},{"h":"صفات يجتنبونها","x":"ترك نصرة الإسلام والقعود عن الجهاد حال وجوبه، والبخل، وموالاة الكفار."},{"h":"ابن عاشور","x":"في الوعد بالاستخلاف إيماء إلى التهيؤ لتحصيل أسبابه مع ضمان التوفيق."}]}],"quiz":[{"q":"ما الذي تكشفه حملة فرعون على موسى ومن معه بوصفهم ﴿لَشِرْذِمَةٌ قَلِيلُونَ﴾؟","o":["نشاط الآلة الإعلامية في تشويه أهل الحق","صدق فرعون في تقدير عدد بني إسرائيل","خوف فرعون الحقيقي من قلة عددهم وضعفهم","حرص فرعون الصادق على حماية الناس من الفتنة"],"why":"ومن الواضح كذلك أن الآلة الإعلامية للحكومة الفرعونية تعمل بنشاط وفي جميع الحالات","pg":95},{"q":"لماذا كرر الله ذكر مصارع الكافرين في كتابه بحسب المؤلف؟","o":["ليتفكر المؤمنون فيها ويعتبروا بها","لأنها أحداث تاريخية لن تتكرر أبداً","لتخويف الأنبياء من مصير أقوامهم المكذبين","لبيان قوة الطغاة وطول ملكهم في الأرض"],"why":"إهلاك الظالمين أمر عظيم، يُحبّ الله تعالى منا أن نتفكر فيه، ونقف عنده، ونتأمله، ونعتبر به","pg":96},{"q":"قال قائل: الأنبياء عندهم وعد بالنصر، أما المصلحون بعدهم فلا. فبم يجيب الكتاب؟","o":["سنن الله ماضية ومعيته للصابرين والمتقين","المعية خاصة بالأنبياء فلا يطمع فيها غيرهم","المعية تنال بالانتساب إلى الأنبياء","المعية انقطعت بانقطاع الوحي كله"],"why":"فالمعية لا تخص الأنبياء وحدهم.","pg":97},{"q":"ما الصفة المركزية التي جعلها الله سبباً لتوريث بني إسرائيل الأرض؟","o":["الصبر","العلم","القوة","الكثرة"],"why":"أنّ الصفة المركزية التي جعلها الله سبباً لتوريث بني إسرائيل الأرض هي (الصبر)","pg":101},{"q":"أي هذه الصفات جعلها المؤلف من صفات المستبدلين التي ينبغي اجتنابها؟","o":["البخل وترك الإنفاق في سبيل الله","الذلة للمؤمنين والعزة على الكافرين","الاستمساك بالوحي والتوكل على الله","عدم الخوف من الخلق في ذات الله"],"why":"وكذلك عليهم أن يجتنبوا الصفات التي ذكرها الله في المستبدلين، ومن أهمها: (ترك نصرة الإسلام والقعود عن الجهاد في سبيل الله حال وجوبه، البخل وترك الإنفاق في سبيل الله، موالاة الكفار والمسارعة فيهم)","pg":100}],"scene":{"t":"ظالم متمكن","x":"يقول لك طالب: هذا الظالم متمكن منذ سنين طويلة، ولا أظن أن حاله ستتغير.","opts":["تذكره بأن سنن الله جارية وتدعوه للاعتبار بمصارع الظالمين","توافقه على أن قوته لا تزول","تصرفه عن التفكير في الأمر"],"why":"وإذا كان هذا في التاريخ فإن سنة الله لا تزال جارية، فليعتبر المؤمن بمصارع الظالمين","pg":96}},{"k":"c10","t":"أنوار من قصة موسى: آيات من سورة المائدة، وآيات من سورة الأعراف (3)","q":"لماذا يتأخر النصر، وكيف يتزود المصلح في طريقه؟","essence":"الأسباب والخوف من الله والتزود بالعبادة","kw":["الشكر","الأسباب","الخلوة"],"sections":[{"t":"تذكر النعمة","pg":104,"key":"فإذا تذكر المؤمن أيام الفقر والذل والقلة، وأن الله سبحانه إنما هو الذي كثّرهم وقواهم، عاد إليه رشده، وخضع وتواضع.","p":["أنّ من صور شكر الله على نعمه: العمل لدينه والجهاد في سبيله"],"items":[{"h":"الآيات","x":"سورة المائدة، الآيات 20 إلى 26."},{"h":"دائم الشكر","x":"تذكر النعمة يجعل المصلح دائم الشكر ودائم التواضع، لأن النصر قد يؤدي إلى البطر."}]},{"t":"الوعد لا يغني عن الأسباب","pg":104,"key":"أنّ الله سبحانه وإن كان قد كتب النصر للمسلمين في معركة أو مرحلة؛ فإن سنته تقتضي أن يبذل المؤمنون الأسباب في تحقيق هذا النصر، ولا ينتظروا الوعد الإلهي دون عمل","p":["ولكنهم لفسادهم، ولجبنهم وخورهم أرادوا أن يتحقق الوعد دون بذل وعمل"],"items":[{"h":"سنة الله","x":"تقتضي ألا يخرج الجبارون منها هكذا دون سبب وبذل."}]},{"t":"الخوف من الله والتوكل","pg":105,"key":"أن الخوف من الله تعالى من أعظم أسباب الثبات وقت الشدائد والأزمات، فمن أراد تربية الشباب على الثبات عند الأزمات فليغرس فيهم مخافة الله تعالى","p":["فالخائف من الله يصغر عنده معنى الخوف من غيره","أن التوكل على الله من أعظم الأعمال التي ينبغي استحضارها عند مواجهة الأعداء"],"items":[{"h":"تحمل النصيحة","x":"قام الرجلان الداعيان بتحريض قومهما مع وجود نبي الله موسى، كمبادرة أبي بكر في دعوة عثمان وعبد الرحمن بن عوف."}]},{"t":"لماذا يتأخر النصر؟","pg":106,"key":"ولذلك فليتنبه العاملون في مختلف الميادين الإصلاحية ممن يلهيهم الشقاق والنزاع والخصومات مع كون طريق الإصلاح واضحاً، والحاجة إلى التركيز عليه ملحّة","p":["أن النصر قد يتأخر ولو وُجد الصادقون والناصحون، إذا كانت هناك حالة عامة من الانحراف والفساد بين العاملين"],"items":[{"h":"التيه","x":"كانوا على وشك دخول الباب فصاروا يتيهون في الأرض أربعين سنة."},{"h":"حاشية","x":"ذكر المؤلف أن الفائدة الأخيرة أشار إليها أحد طلابه."}]},{"t":"الخلوة والاستخلاف","pg":110,"key":"المصلح يحتاج إلى فترات انقطاع للتعبد يتزود فيها، ويتفكر ويتأمّل، وهذه من الأمور المهمة جداً","p":["لا ينبغي للمصلح إذا أراد أن يتفرّغ لبعض الأعمال التعبدية أو العلمية أن يضيّع مَن وراءه من الطلاب والمدعوين، وإنما يولي عليهم من يقوم بشأنهم"],"items":[{"h":"الآيات","x":"سورة الأعراف، الآيات 142 إلى 144."},{"h":"الميقات","x":"واعد الله موسى أربعين ليلة يتهيأ فيها بالتعبد والصيام استعداداً للمناجاة."},{"h":"الاعتكاف","x":"كان النبي ﷺ يعتزل في العشر الأواخر من رمضان بالاعتكاف."}]},{"t":"العلم بالله ونعمة الهداية","pg":111,"key":"بيانٌ بأن النعم لا تنحصر في الأشياء المادية، بل إنّ من أعظم النعم التي تستوجب الشكر نعمة الهداية ونعمة العلم بالله وبشريعته.","p":["بيانٌ بأنّ من أعظم ما ينبغي أن يُفاضل به الخلق هو مدى امتلاكهم لمصدر الإرشاد الإلهي ومدى العلم به"],"items":[{"h":"الازدياد من العلم بالله","x":"أهمية الازدياد من التعرف على الله وإن بلغ المؤمن ما بلغ من العلم والدعوة."},{"h":"الاستفادة ممن هو أعلم","x":"المصلح وإن بلغ من العلم ما بلغ يحتاج إلى الاستفادة ممن هو أعلم منه."}]}],"quiz":[{"q":"ما أثر تذكر المؤمن أيام الفقر والذل والقلة بعد أن يكثّره الله ويقويه؟","o":["يعود إليه رشده فيخضع ويتواضع","يزداد حزنه على ما فاته من الخير","يحمله ذلك على الانتقام ممن ظلمه","يشعر بأن ما بلغه ثمرة جهده وحده"],"why":"فإذا تذكر المؤمن أيام الفقر والذل والقلة، وأن الله سبحانه إنما هو الذي كثّرهم وقواهم، عاد إليه رشده، وخضع وتواضع.","pg":104},{"q":"أخبر موسى قومه أن الأرض المقدسة مكتوبة لهم، فلماذا لم يدخلوها؟","o":["أرادوا تحقق الموعود دون بذل وعمل","لأن الأمر كان خاصاً بموسى وهارون","لأن الجبارين خرجوا منها قبل وصولهم","لأن هارون أمرهم بالانتظار في التيه"],"why":"ولكنهم لفسادهم، ولجبنهم وخورهم أرادوا أن يتحقق الوعد دون بذل وعمل","pg":105},{"q":"من أراد تربية الناشئة على الثبات عند الأزمات، فما الذي يغرسه فيهم بحسب الكتاب؟","o":["مخافة الله تعالى في قلوبهم","الثقة المطلقة بقدراتهم الذاتية","حب المغامرة وركوب الصعاب","الحذر الشديد من كل الناس"],"why":"فمن أراد تربية الشباب على الثبات عند الأزمات فليغرس فيهم مخافة الله تعالى","pg":105},{"q":"لماذا قد يتأخر النصر مع وجود الصادقين والناصحين؟","o":["لحالة عامة من الانحراف بين العاملين","لأن الصادقين قلة لا أثر لهم أصلاً","لأن النصر لا يرتبط بالأعمال والأسباب مطلقاً","لأن الأعداء أكثر عدداً وعدة دائماً"],"why":"أن النصر قد يتأخر ولو وُجد الصادقون والناصحون، إذا كانت هناك حالة عامة من الانحراف والفساد بين العاملين","pg":106},{"q":"أراد معلم أن يتفرغ أياماً للعبادة، فما الذي يصنعه بمن يتابعهم من الطلاب؟","o":["يولي عليهم من يقوم بشأنهم","يتركهم دون متابعة حتى يعود إليهم","يؤجل تفرغه حتى يتخرجوا جميعاً","يكلفهم بمرافقته في خلوته وعبادته"],"why":"لا ينبغي للمصلح إذا أراد أن يتفرّغ لبعض الأعمال التعبدية أو العلمية أن يضيّع مَن وراءه من الطلاب والمدعوين، وإنما يولي عليهم من يقوم بشأنهم","pg":110}],"scene":{"t":"نزاع في الفريق","x":"فريق من المعلمين يعمل على مبادرة واضحة الهدف، لكن الخلافات الشخصية بدأت تشغلهم عنها.","opts":["يعالج الشقاق ويرد الجهود إلى الهدف","يتجاهل النزاع ما دام الهدف واضحاً","ينسحب من الفريق ويعمل وحده"],"why":"ولذلك فليتنبه العاملون في مختلف الميادين الإصلاحية ممن يلهيهم الشقاق والنزاع والخصومات مع كون طريق الإصلاح واضحاً، والحاجة إلى التركيز عليه ملحّة","pg":106}},{"k":"c11","t":"أنوار من قصة موسى: آيات من سورة الكهف، وآيات من سورة القصص (3)، والخاتمة","q":"ما أخلاق طالب العلم والمصلح، وما وظائف أهل العلم؟","essence":"التواضع وعلو الهمة ووظائف أهل العلم","kw":["طلب العلم","التواضع","العزيمة"],"sections":[{"t":"طلب الازدياد والتواضع","pg":114,"key":"أهمية محافظة المصلح على خُلُق التواضع","p":["مهما بلغ الإنسان من العلم فهو يحتاج إلى الازدياد، ويجب أن يظل متطلباً للازدياد","وهذا ما ينبغي أن يتذكره المصلح كلما عظمت نفسه ولاحت بوادر العُجب لديه."],"items":[{"h":"الآيات","x":"سورة الكهف، الآيات 60 إلى 70."},{"h":"موسى والخضر","x":"موسى أفضل من الخضر، ومع ذلك تواضع ورحل وتعب ليلقاه ويتعلم منه، وقبل بشرطه."}]},{"t":"كيد الشيطان والغاية العظيمة","pg":115,"key":"أن طالب الغايات العظيمة لا ينبغي أن يلتفت إلى المشتتات والعوائق الجزئية","p":["الشيطان له عمل خاص في إفشال خطوات المصلحين، وأحيانًا يكون ذلك بالعمل على الدوائر القريبة منهم"],"items":[{"h":"فتى موسى","x":"أنسى الشيطان الفتى ذكر الحوت ليعطل مطلب موسى، كما أنسى صاحب يوسف ذكره عند الملك."},{"h":"الرحلة في طلب العلم","x":"أخرج البخاري قصة موسى والخضر في كتاب العلم، وبوّب: باب الخروج في طلب العلم."}]},{"t":"روح العزيمة","pg":115,"key":"أهمية محافظة المصلح على روح العزيمة وأن تبقى همته عالية، وألا تثقله الأحداث والسنون فتهدّ عزيمته وهمته","p":[],"items":[{"h":"لا أبرح","x":"عزم موسى أن يسير حتى يبلغ مجمع البحرين ولو طالت المسافة، فأمضاه الشوق والرغبة."}]},{"t":"وظائف أهل العلم","pg":118,"key":"من أهم وظائف أهل العلم: إصلاح الفساد والأمر بالمعروف والنهي عن المنكر، وخاصة إذا كان المنكر من الرموز البارزة في المجتمع والتي من شأنها أن تؤثّر على الناس.","p":["كما أن من أهم وظائفهم: تصحيح المعايير وتثبيت المؤمنين في الفتن","أن العلم وحده لا يكفي ليكون صاحبه ثابتًا أمام الفتن الدنيوية وبريقها، بل لا بد أن يكون صاحب العلم متصفًا بالصبر حتى يقاوم هذه الفتن"],"items":[{"h":"الآيات","x":"سورة القصص، الآيات 76 إلى 80، في قصة قارون."},{"h":"أثر الدعوة","x":"ظهرت آثار دعوة موسى في أتباع وصفهم الله بأنهم أهل علم، وهذا من وظائف الأنبياء: تربية المؤمنين وتعليمهم."}]},{"t":"الخاتمة","pg":119,"key":"الحمد لله على تمام هذا الجزء من أنوار الأنبياء، والفضل فيه لله سبحانه الذي فتح وبارك","p":["والذي هدى إلى الاهتمام بموضوع الأنبياء في القرآن، والذي وجدتُ فيه البركة والعلم والنور والخير والهدى"],"items":[{"h":"مكان التأليف وتاريخه","x":"إسطنبول، 2 شوال 1444ه."}]}],"quiz":[{"q":"ما الذي يدل عليه رحيل موسى، وهو كليم الله، ليتعلم من الخضر؟","o":["حاجة الإنسان إلى الازدياد مهما بلغ","أن الخضر كان أفضل من موسى منزلة","أن العلم لا يؤخذ إلا بالرحلة البعيدة","أن موسى لم يكن عنده علم التوراة"],"why":"مهما بلغ الإنسان من العلم فهو يحتاج إلى الازدياد، ويجب أن يظل متطلباً للازدياد","pg":113},{"q":"لاحت لمعلم بوادر الإعجاب بنفسه ومكانته، فبم يذكّره الكتاب؟","o":["بتواضع موسى للخضر مع أنه أفضل منه","بأن العلم يرفع صاحبه فوق الناس","بأن المنزلة تستحق الإظهار أحياناً","بأن العجب لا يضر ما دام العمل صالحاً"],"why":"وهذا ما ينبغي أن يتذكره المصلح كلما عظمت نفسه ولاحت بوادر العُجب لديه.","pg":114},{"q":"ماذا فعل موسى حين أخبره فتاه بما كان من أمر الحوت؟","o":["التفت مباشرة إلى الغاية دون توقف","عاتب فتاه طويلاً على تقصيره","رجع إلى أهله لفوات الوقت والجهد","توقف ليستريح من الجهد الزائد أولاً"],"why":"فموسى عليه السلام لم يقف عند نسيان فتاه ولا على ما تسبب به من فوات ما فات من الوقت ولا على الجهد الزائد، بل التفت مباشرة إلى الغاية","pg":115},{"q":"ما الدور الذي قام به الذين أوتوا العلم حين خرج قارون في زينته؟","o":["تصحيح المعايير وتثبيت المؤمنين","مجاراة الناس في تعظيم زينته","اعتزال الناس والانشغال بالعبادة","الاكتفاء بالعلم دون نصح القوم"],"why":"كما أن من أهم وظائفهم: تصحيح المعايير وتثبيت المؤمنين في الفتن","pg":118},{"q":"لماذا لا يكفي العلم وحده لثبات صاحبه أمام بريق الدنيا؟","o":["لأنه يحتاج معه إلى الصبر ليقاوم الفتن","لأن العلم سبب للغرور والعجب في الغالب","لأن الفتن لا يقاومها إلا المال والجاه","لأن الدنيا لا تفتن أهل العلم الراسخين أصلاً"],"why":"أن العلم وحده لا يكفي ليكون صاحبه ثابتًا أمام الفتن الدنيوية وبريقها، بل لا بد أن يكون صاحب العلم متصفًا بالصبر حتى يقاوم هذه الفتن","pg":118}],"scene":{"t":"فتور الهمة","x":"معلم مضى على عمله التربوي سنوات طويلة، وبدأ يشعر أن الأحداث أثقلته وأن همته تضعف.","opts":["يجدد عزيمته ويستحضر شرف غايته","يقبل الفتور لأنه طبيعي مع السنين","يترك العمل لغيره ممن هو أصغر"],"why":"أهمية محافظة المصلح على روح العزيمة وأن تبقى همته عالية، وألا تثقله الأحداث والسنون فتهدّ عزيمته وهمته","pg":115}}],"highlights":[{"x":"فإذا ضحيت في سبيل الله، وصبرت في ذلك؛ فأحسن الظن بربك، فإن عاقبة البلاء حسنة.","pg":17},{"x":"أن ثمرة العلم: «الهداية» وليس الاستكثار من المعلومات.","pg":16},{"x":"ولكل زمان أصنامه وفتنته وتأثيراته","pg":20},{"x":"فليست القضية في العلم المعزول عن العمل، وإنما في العلم الحامل على العمل.","pg":46},{"x":"فالطغيان لا يستمر، لكن ذلك بميزان الله وليس بميزاننا.","pg":52},{"x":"فقد تنفذ الكلمة إلى باطنه وتُحدِث أثرها ولو بعد حين.","pg":71},{"x":"فليتنبّه المؤمن في كل زمان إلى هذا المنطق، ولا يربط بين العلو المادي وبين الحق.","pg":77},{"x":"فالميزان الإلهي يختلف عن الميزان البشري.","pg":86},{"x":"وهذه سنة مستمرة في الظالمين والمجرمين، يستعملون نفس الأسلوب، وما أشبه الليلة بالبارحة.","pg":96},{"x":"فالمعية لا تخص الأنبياء وحدهم.","pg":97},{"x":"فالخائف من الله يصغر عنده معنى الخوف من غيره","pg":105}],"concepts":[{"term":"الصديقية","def":"والصديقية متعلقة بكمال التصديق بالله وخبره ووعده، كما أنها متعلقة بتمام الصدق في الأقوال والأفعال","pg":13},{"term":"الحنفاء","def":"المائلين عن الشرك المتبرئين منه، المقبلين إلى الله إقبال إخلاص وتوحيد","pg":22},{"term":"تحقيق التوحيد","def":"إن هذا التحقيق لا يكون إلا بالجمع بين «النفي» و «الإثبات»؛ نفي الألوهية عما سوى الله تعالى، وإثباتها له وحده","pg":22},{"term":"التنزل مع الخصم","def":"على وجه التنزل مع الخصم أي: هذا ربي، فهلم ننظر، هل يستحق الربوبية؟ وهل يقوم لنا دليل على ذلك؟","pg":22},{"term":"ملة إبراهيم","def":"التي هي الاستسلام لله وحده والبراءة من الشرك وأهله","pg":33},{"term":"الأوّاه","def":"بأنه الدعّاء، أي كثير الدعاء","pg":33},{"term":"الحواري","def":"والحواريُّ: الناصر.","pg":52},{"term":"القواعد الكبرى لأعمال القلوب","def":"وهي: (اليقين، والمحبة، والخشية).","pg":57},{"term":"مرتبة الإحسان","def":"الاستحضار الدائم لمراقبته «مرتبة الإحسان».","pg":65},{"term":"ابتلاء مرحلة الاستضعاف","def":"فأما ابتلاء مرحلة الاستضعاف فالقتل والأسر والتعذيب والاستعباد والاستهزاء والسخرية والمنع من التعبد وإقامة الدين","pg":86},{"term":"ابتلاء مرحلة التمكين","def":"وأما ابتلاء مرحلة التمكين ففتنة الدنيا والتنافس والتحاسد والتدابر والغرور، وفتنة الانصراف عن التعبد وعن الاستقامة انشغالاً بالمغريات والمكتسبات المادية","pg":86},{"term":"سنة الاستبدال","def":"وكذلك في سنة أخرى مقاربة لوراثة الأرض، وهي سنة الاستبدال.","pg":100}],"links":[{"topic":"الحوار وأدب النصيحة للوالدين","pg":14},{"topic":"العلم والعمل","pg":46},{"topic":"اليقين","pg":75},{"topic":"الدعاء","pg":36},{"topic":"الصلاة","pg":92},{"topic":"تربية الشباب","pg":90},{"topic":"التوكل","pg":91},{"topic":"الصبر","pg":101},{"topic":"التواضع","pg":114},{"topic":"الإعلام وتشويه الحق","pg":95}]};
